//! High-level AST for one script *before* it is lowered to byte-code.

#[derive(Debug, Clone, PartialEq)]
pub struct Text {
    pub text: String,
    pub index: u16, // numeric id assigned by the parser
}

/* ------------------------------------------------------------------------- */
/*  Opcodes                                                                  */
/* ------------------------------------------------------------------------- */

/// One-byte discriminant that uniquely identifies the command variant inside
/// the generated byte-code stream.
///
/// NOTE: The numeric values **must stay in sync** with the order of
/// `Cmd::VARIANT_NAMES` because external tooling may rely on that mapping.
#[repr(u8)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Opcode {
    Msg = 0,
    TMsg,
    SMsg,
    Tp,
    TpIf,
    If,
    SetFlag,
    UnsetFlag,
    ReadFlag,
    GiveItem,
    End = 255,
}

/* ------------------------------------------------------------------------- */
/*  GiveItem contract (revision 2026-10-12)                                  */
/* ------------------------------------------------------------------------- */

/// `giveitem <kind> <id> <count>` operand bounds. Frozen: the firmware profile
/// (jp8.5.17) consumes exactly these values and the three operand bytes
/// (`kind`, `id`, `count`) follow opcode 9 in that order.
pub const GIVE_ITEM_KIND_LURE: u16 = 0;
pub const GIVE_ITEM_KIND_CONSUMABLE: u16 = 1;
pub const GIVE_ITEM_KIND_KEY: u16 = 2;

pub const GIVE_ITEM_LURE_MAX_ID: u16 = 23;
pub const GIVE_ITEM_CONSUMABLE_MAX_ID: u16 = 7;
pub const GIVE_ITEM_KEY_MAX_ID: u16 = 7;
pub const GIVE_ITEM_MAX_COUNT: u16 = 99;

/// Validate authored `giveitem` operands *before* any byte is emitted.
///
/// Returns the first violation as a human-readable host-side diagnostic. The
/// values arrive as `u16` from the lexer so out-of-range authoring (for
/// example `giveitem 0 300 1`) is rejected rather than truncated.
pub fn validate_give_item(kind: u16, id: u16, count: u16) -> Result<(), String> {
    let (max_id, is_key) = match kind {
        GIVE_ITEM_KIND_LURE => (GIVE_ITEM_LURE_MAX_ID, false),
        GIVE_ITEM_KIND_CONSUMABLE => (GIVE_ITEM_CONSUMABLE_MAX_ID, false),
        GIVE_ITEM_KIND_KEY => (GIVE_ITEM_KEY_MAX_ID, true),
        _ => {
            return Err(format!(
                "invalid kind {kind}: expected 0 (lure), 1 (consumable) or 2 (key)"
            ))
        }
    };
    if id > max_id {
        return Err(format!("invalid id {id} for kind {kind}: max {max_id}"));
    }
    if is_key {
        if count != 1 {
            return Err(format!("key grants require count 1, got {count}"));
        }
    } else if !(1..=GIVE_ITEM_MAX_COUNT).contains(&count) {
        return Err(format!(
            "invalid count {count}: expected 1..={GIVE_ITEM_MAX_COUNT}"
        ));
    }
    Ok(())
}

impl From<Opcode> for u8 {
    #[inline(always)]
    fn from(op: Opcode) -> Self {
        op as u8
    }
}

/* ------------------------------------------------------------------------- */
/*  AST nodes                                                                */
/* ------------------------------------------------------------------------- */

#[derive(Debug, Clone, PartialEq)]
pub enum Location {
    Cords(u16, u16),
    Tag(Text), // ← uses Text now
}

#[derive(Debug, Clone, PartialEq)]
pub enum Branch {
    ThenElse(Box<Cmd>, Box<Cmd>),
    Then(Box<Cmd>),
}

#[derive(Debug, Clone, PartialEq)]
pub enum Condition {
    FlagSet(Text),   // flag_X
    FlagClear(Text), // !flag_X
}

#[derive(Debug, Clone, PartialEq)]
pub enum Cmd {
    Msg {
        text: Text,
    },

    TMsg {
        at: Location,
        text: Text,
    },

    SMsg {
        selected: Location,
        text: Text,
    },

    Tp {
        to: Location,
    },
    TpIf {
        from: Location,
        to: Location,
    },

    If {
        condition: Condition,
        branches: Branch,
    },

    SetFlag {
        flag: Text,
    },
    UnsetFlag {
        flag: Text,
    },
    ReadFlag {
        flag: Text,
    },

    GiveItem {
        kind: u8,
        id: u8,
        count: u8,
    },

    End,
}

impl Cmd {
    /// Human-readable names that correspond 1-to-1 to the numeric opcodes.
    pub const VARIANT_NAMES: &'static [&'static str] = &[
        "Msg",
        "TMsg",
        "SMsg",
        "Tp",
        "TpIf",
        "If",
        "SetFlag",
        "UnsetFlag",
        "ReadFlag",
        "GiveItem",
        "End",
    ];

    /// Return the single-byte opcode for this command.
    #[inline(always)]
    pub fn opcode(&self) -> Opcode {
        match self {
            Cmd::Msg { .. } => Opcode::Msg,
            Cmd::TMsg { .. } => Opcode::TMsg,
            Cmd::SMsg { .. } => Opcode::SMsg,
            Cmd::Tp { .. } => Opcode::Tp,
            Cmd::TpIf { .. } => Opcode::TpIf,
            Cmd::If { .. } => Opcode::If,
            Cmd::SetFlag { .. } => Opcode::SetFlag,
            Cmd::UnsetFlag { .. } => Opcode::UnsetFlag,
            Cmd::ReadFlag { .. } => Opcode::ReadFlag,
            Cmd::GiveItem { .. } => Opcode::GiveItem,
            Cmd::End => Opcode::End,
        }
    }
}

/* ------------------------------------------------------------------------- */
/*  Byte-code generation                                                     */
/* ------------------------------------------------------------------------- */

/// Everything that can be put into the final byte-stream implements this trait.
pub trait ToBytecode {
    fn to_bytes(&self) -> Vec<u8>;
}

/* -------- Helper ---------- */

fn write_u16(v: u16, out: &mut Vec<u8>) {
    out.extend_from_slice(&v.to_be_bytes());
}

/* -------- Implementations -- */

impl ToBytecode for Text {
    fn to_bytes(&self) -> Vec<u8> {
        self.index.to_be_bytes().to_vec()
    }
}

impl ToBytecode for Location {
    fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        match self {
            Location::Cords(x, y) => {
                write_u16(*x, &mut buf);
                write_u16(*y, &mut buf);
            }
            Location::Tag(t) => {
                buf.push(255);
                buf.extend_from_slice(&t.to_bytes());
            }
        }
        buf
    }
}

impl ToBytecode for Condition {
    fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        match self {
            Condition::FlagSet(f) => {
                buf.push(0);
                buf.extend_from_slice(&f.to_bytes());
            }
            Condition::FlagClear(f) => {
                buf.push(1);
                buf.extend_from_slice(&f.to_bytes());
            }
        }
        buf
    }
}

impl ToBytecode for Branch {
    fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        match self {
            Branch::ThenElse(then_cmd, else_cmd) => {
                buf.push(0);
                let then = then_cmd.to_bytes();
                buf.push(then.len() as u8);
                buf.extend_from_slice(&then);
                buf.extend_from_slice(&else_cmd.to_bytes());
            }
            Branch::Then(cmd) => {
                buf.push(1); // TODO: Don't think need this?
                let branch = &cmd.to_bytes();
                buf.push(branch.len() as u8);
                buf.extend_from_slice(branch);
            }
        }
        buf
    }
}

impl ToBytecode for Cmd {
    fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        buf.push(u8::from(self.opcode())); // 1-byte discriminant

        match self {
            Cmd::Msg { text } => {
                buf.extend_from_slice(&text.to_bytes());
            }
            Cmd::TMsg { at, text } => {
                buf.extend_from_slice(&at.to_bytes());
                buf.extend_from_slice(&text.to_bytes());
            }
            Cmd::SMsg { selected, text } => {
                buf.extend_from_slice(&selected.to_bytes());
                buf.extend_from_slice(&text.to_bytes());
            }
            Cmd::Tp { to } => {
                buf.extend_from_slice(&to.to_bytes());
            }
            Cmd::TpIf { from, to } => {
                buf.extend_from_slice(&from.to_bytes());
                buf.extend_from_slice(&to.to_bytes());
            }
            Cmd::If {
                condition,
                branches,
            } => {
                buf.extend_from_slice(&condition.to_bytes());
                buf.extend_from_slice(&branches.to_bytes());
            }
            Cmd::SetFlag { flag } | Cmd::UnsetFlag { flag } | Cmd::ReadFlag { flag } => {
                buf.extend_from_slice(&flag.to_bytes());
            }
            Cmd::GiveItem { kind, id, count } => {
                // Exactly three unsigned byte operands, in order.
                buf.push(*kind);
                buf.push(*id);
                buf.push(*count);
            }
            Cmd::End => { /* nothing extra */ }
        }
        buf
    }
}

/* ------------------------------------------------------------------------- */
/*  Unit-tests                                                               */
/* ------------------------------------------------------------------------- */

#[cfg(test)]
mod tests {
    use super::*;

    // ──────────────────────────────────────────────────────────────────────
    //  Helpers
    // ──────────────────────────────────────────────────────────────────────

    fn txt(idx: u16, s: &str) -> Text {
        Text {
            text: s.into(),
            index: idx,
        }
    }

    // ──────────────────────────────────────────────────────────────────────
    //  Primitive types
    // ──────────────────────────────────────────────────────────────────────

    #[test]
    fn test_text_to_bytes() {
        let t = txt(0x1224, "dummy");
        assert_eq!(t.to_bytes(), vec![0x12, 0x24]); // little-endian
    }

    #[test]
    fn test_location_to_bytes() {
        // Cords
        let loc = Location::Cords(1, 2);
        assert_eq!(loc.to_bytes(), vec![0, 1, 0, 2]);

        // Tag
        let loc = Location::Tag(txt(7, "tag"));
        assert_eq!(loc.to_bytes(), vec![255, 0, 7]);
    }

    // ──────────────────────────────────────────────────────────────────────
    //  Commands
    // ──────────────────────────────────────────────────────────────────────

    #[test]
    fn test_cmd_msg() {
        let cmd = Cmd::Msg { text: txt(3, "hi") };
        // opcode 0 (Msg) + text-index 3 (u16 LE)
        assert_eq!(cmd.to_bytes(), vec![0, 0, 3]);
    }

    #[test]
    fn test_cmd_tmsg_tag() {
        let cmd = Cmd::TMsg {
            at: Location::Tag(txt(1, "place")),
            text: txt(2, "hello"),
        };
        // opcode 1  | Location(Tag) => 1, idx 1  | text-idx 2
        assert_eq!(cmd.to_bytes(), vec![1, 255, 0, 1, 0, 2]);
    }

    #[test]
    fn test_cmd_tp_cords() {
        let cmd = Cmd::TpIf {
            from: Location::Cords(1, 2),
            to: Location::Cords(3, 4),
        };
        // opcode 2
        //  from:  1,0, 2,0
        //  to  :  3,0, 4,0
        assert_eq!(
            cmd.to_bytes(),
            vec![Opcode::TpIf as u8, 0, 1, 0, 2, 0, 3, 0, 4]
        );
    }

    #[test]
    fn test_cmd_setflag() {
        let cmd = Cmd::SetFlag {
            flag: txt(5, "flag"),
        };
        assert_eq!(cmd.to_bytes(), vec![Opcode::SetFlag as u8, 0, 5]); // opcode 4
    }

    // ── GiveItem (opcode 9, contract revision 2026-10-12) ────────────────

    #[test]
    fn test_giveitem_opcode_number() {
        // Existing numbers are frozen; GiveItem is appended at 9 and End
        // stays at 255.
        assert_eq!(u8::from(Opcode::ReadFlag), 8);
        assert_eq!(u8::from(Opcode::GiveItem), 9);
        assert_eq!(u8::from(Opcode::End), 255);
    }

    #[test]
    fn test_cmd_giveitem_bytes() {
        // Four-byte pinned stream: opcode + kind + id + count.
        let cmd = Cmd::GiveItem {
            kind: 0,
            id: 23,
            count: 99,
        };
        assert_eq!(cmd.to_bytes(), vec![9, 0, 23, 99]);
        assert_eq!(cmd.to_bytes().len(), 4);
    }

    #[test]
    fn test_cmd_giveitem_variant_name_index() {
        // VARIANT_NAMES is indexed by the numeric opcode elsewhere (the Tauri
        // editor), so GiveItem must occupy slot 9.
        assert_eq!(Cmd::VARIANT_NAMES[9], "GiveItem");
        assert_eq!(Cmd::VARIANT_NAMES[8], "ReadFlag");
        assert_eq!(Cmd::VARIANT_NAMES[Cmd::VARIANT_NAMES.len() - 1], "End");
    }

    #[test]
    fn test_validate_give_item_boundaries() {
        // Inclusive boundaries for every kind.
        assert!(validate_give_item(0, 0, 1).is_ok());
        assert!(validate_give_item(0, 23, 99).is_ok());
        assert!(validate_give_item(1, 0, 1).is_ok());
        assert!(validate_give_item(1, 7, 99).is_ok());
        assert!(validate_give_item(2, 0, 1).is_ok());
        assert!(validate_give_item(2, 7, 1).is_ok());
    }

    #[test]
    fn test_validate_give_item_rejections() {
        assert!(validate_give_item(3, 0, 1).is_err(), "unsupported kind");
        assert!(validate_give_item(0, 24, 1).is_err(), "lure id too high");
        assert!(validate_give_item(1, 8, 1).is_err(), "consumable id too high");
        assert!(validate_give_item(2, 8, 1).is_err(), "key id too high");
        assert!(validate_give_item(0, 0, 0).is_err(), "count zero");
        assert!(validate_give_item(0, 0, 100).is_err(), "count too high");
        assert!(validate_give_item(2, 0, 2).is_err(), "key count must be one");
        assert!(validate_give_item(2, 0, 0).is_err(), "key count zero");
    }
}
